sys_script_email.script:
(function runMailScript( /* GlideRecord */ current, /* TemplatePrinter */ template,
    /* Optional EmailOutbound */
    email, /* Optional GlideRecord */ email_action,
    /* Optional GlideRecord */
    event) {


    var url = gs.getProperty("glide.servlet.uri") + "services?id=hoc_hrm_todos_page&amp;table=sn_hr_core_task&amp;sys_id=" + current.sys_id;
    url = url + "&amp;lang=fq";

    template.print("<a title=" + 'link' + " href='" + url + "'" + "target=" + '_blank' + " rel=" + 'noopener' + ">lien</a>" + " ci-dessous pour visualiser les détails de l'enquête et accepter ou refuser leurs conclusions.</p>");

    // Add your code here



})(current, template, email, email_action, event);
